var RS_DAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
var RS_MONS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

function p2(n){ return (n < 10 ? '0' : '') + n; }

function escapeXml(s){
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}

function parseDate(s){
  var t = String(s == null ? '' : s).trim();
  if (!t) return null;
  var m = /^(\d{4})-(\d{2})-(\d{2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2}))?)?\s*(Z|[+-]\d{2}:?\d{2})?$/.exec(t);
  if (m){
    var ms = Date.UTC(+m[1], (+m[2]) - 1, +m[3], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
    var tz = m[7];
    if (tz && tz !== 'Z'){
      var sign = tz.charAt(0) === '-' ? -1 : 1;
      var digits = tz.slice(1).replace(':', '');
      ms -= sign * (parseInt(digits.slice(0, 2), 10) * 60 + parseInt(digits.slice(2, 4), 10)) * 60000;
    }
    return new Date(ms);
  }
  var d = new Date(t);
  return isNaN(d.getTime()) ? null : d;
}

function rfc822(d){
  if (!d) return '';
  return RS_DAYS[d.getUTCDay()] + ', ' + p2(d.getUTCDate()) + ' ' + RS_MONS[d.getUTCMonth()] + ' ' +
         d.getUTCFullYear() + ' ' + p2(d.getUTCHours()) + ':' + p2(d.getUTCMinutes()) + ':' +
         p2(d.getUTCSeconds()) + ' GMT';
}

function rfc3339(d){
  if (!d) return '';
  return d.getUTCFullYear() + '-' + p2(d.getUTCMonth() + 1) + '-' + p2(d.getUTCDate()) + 'T' +
         p2(d.getUTCHours()) + ':' + p2(d.getUTCMinutes()) + ':' + p2(d.getUTCSeconds()) + 'Z';
}

function finishItem(c){
  return {
    title: c.title, url: c.url || '', date: c.date || '', author: c.author || '',
    tags: c.tags || [], guid: c.guid || c.url || c.title,
    image: c.image || '', description: c.body.join('\n').replace(/^\s+|\s+$/g, '')
  };
}

function parseItems(text){
  var lines = String(text == null ? '' : text).split(/\r?\n/);
  var items = [], cur = null;
  for (var i = 0; i < lines.length; i++){
    var ln = lines[i];
    var h = /^#\s+(.*)$/.exec(ln);
    if (h){
      if (cur) items.push(finishItem(cur));
      cur = { title: h[1].replace(/^\s+|\s+$/g, ''), body: [], tags: [] };
      continue;
    }
    if (!cur) continue;
    var kv = /^\s*(url|link|date|author|tags|guid|image)\s*:\s*(.*)$/i.exec(ln);
    if (kv){
      var k = kv[1].toLowerCase(), v = kv[2].replace(/^\s+|\s+$/g, '');
      if (k === 'link') k = 'url';
      if (k === 'tags'){
        cur.tags = v ? v.split(/[,\uFF0C]/).map(function(x){ return x.replace(/^\s+|\s+$/g, ''); })
                        .filter(function(x){ return !!x; }) : [];
      } else cur[k] = v;
      continue;
    }
    cur.body.push(ln);
  }
  if (cur) items.push(finishItem(cur));
  return items;
}

function latestDate(items, fallback){
  var best = null;
  for (var i = 0; i < items.length; i++){
    var d = parseDate(items[i].date);
    if (d && (!best || d.getTime() > best.getTime())) best = d;
  }
  return best || (fallback ? parseDate(fallback) : null);
}

function buildRss(feed, items){
  feed = feed || {}; items = items || [];
  var L = [];
  L.push('<?xml version="1.0" encoding="UTF-8"?>');
  L.push('<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom" xmlns:dc="http://purl.org/dc/elements/1.1/">');
  L.push('  <channel>');
  L.push('    <title>' + escapeXml(feed.title || '未命名订阅源') + '</title>');
  L.push('    <link>' + escapeXml(feed.link || '') + '</link>');
  L.push('    <description>' + escapeXml(feed.description || '') + '</description>');
  L.push('    <language>' + escapeXml(feed.language || 'zh-CN') + '</language>');
  if (feed.self) L.push('    <atom:link href="' + escapeXml(feed.self) + '" rel="self" type="application/rss+xml"/>');
  var last = latestDate(items, feed.now);
  if (last) L.push('    <lastBuildDate>' + rfc822(last) + '</lastBuildDate>');
  L.push('    <generator>RssForge (nano-tools)</generator>');
  for (var i = 0; i < items.length; i++){
    var it = items[i], d = parseDate(it.date);
    L.push('    <item>');
    L.push('      <title>' + escapeXml(it.title || '') + '</title>');
    if (it.url) L.push('      <link>' + escapeXml(it.url) + '</link>');
    var permalink = (!!it.url && it.guid === it.url) ? 'true' : 'false';
    L.push('      <guid isPermaLink="' + permalink + '">' + escapeXml(it.guid || '') + '</guid>');
    if (d) L.push('      <pubDate>' + rfc822(d) + '</pubDate>');
    if (it.author) L.push('      <dc:creator>' + escapeXml(it.author) + '</dc:creator>');
    for (var t = 0; t < (it.tags || []).length; t++) L.push('      <category>' + escapeXml(it.tags[t]) + '</category>');
    if (it.description) L.push('      <description>' + escapeXml(it.description) + '</description>');
    L.push('    </item>');
  }
  L.push('  </channel>');
  L.push('</rss>');
  return L.join('\n');
}

function buildAtom(feed, items){
  feed = feed || {}; items = items || [];
  var last = latestDate(items, feed.now);
  var L = [];
  L.push('<?xml version="1.0" encoding="UTF-8"?>');
  L.push('<feed xmlns="http://www.w3.org/2005/Atom" xml:lang="' + escapeXml(feed.language || 'zh-CN') + '">');
  L.push('  <title>' + escapeXml(feed.title || '未命名订阅源') + '</title>');
  L.push('  <subtitle>' + escapeXml(feed.description || '') + '</subtitle>');
  L.push('  <id>' + escapeXml(feed.self || feed.link || 'urn:rssforge:feed') + '</id>');
  if (feed.link) L.push('  <link rel="alternate" href="' + escapeXml(feed.link) + '"/>');
  if (feed.self) L.push('  <link rel="self" href="' + escapeXml(feed.self) + '"/>');
  if (last) L.push('  <updated>' + rfc3339(last) + '</updated>');
  L.push('  <generator uri="https://wangzifan396-wzf.github.io/WB/tools/RssForge/">RssForge</generator>');
  for (var i = 0; i < items.length; i++){
    var it = items[i], d = parseDate(it.date);
    L.push('  <entry>');
    L.push('    <title>' + escapeXml(it.title || '') + '</title>');
    L.push('    <id>' + escapeXml(it.guid || it.url || it.title || '') + '</id>');
    if (it.url) L.push('    <link rel="alternate" href="' + escapeXml(it.url) + '"/>');
    if (d) L.push('    <updated>' + rfc3339(d) + '</updated>');
    if (it.author) L.push('    <author><name>' + escapeXml(it.author) + '</name></author>');
    for (var t = 0; t < (it.tags || []).length; t++) L.push('    <category term="' + escapeXml(it.tags[t]) + '"/>');
    if (it.description) L.push('    <summary type="text">' + escapeXml(it.description) + '</summary>');
    L.push('  </entry>');
  }
  L.push('</feed>');
  return L.join('\n');
}

function buildJsonFeed(feed, items){
  feed = feed || {}; items = items || [];
  var out = {
    version: 'https://jsonfeed.org/version/1.1',
    title: feed.title || '未命名订阅源',
    home_page_url: feed.link || undefined,
    feed_url: feed.self || undefined,
    description: feed.description || undefined,
    language: feed.language || 'zh-CN',
    items: []
  };
  for (var i = 0; i < items.length; i++){
    var it = items[i], d = parseDate(it.date), row = {};
    row.id = it.guid || it.url || it.title || String(i + 1);
    if (it.url) row.url = it.url;
    row.title = it.title || '';
    if (it.description) row.content_text = it.description;
    if (d) row.date_published = rfc3339(d);
    if (it.author) row.authors = [{ name: it.author }];
    if (it.tags && it.tags.length) row.tags = it.tags;
    if (it.image) row.image = it.image;
    out.items.push(row);
  }
  return JSON.stringify(out, null, 2);
}

function lintFeed(feed, items){
  feed = feed || {}; items = items || [];
  var issues = [];
  if (!feed.title) issues.push({ level:'bad', msg:'订阅源缺少标题，阅读器会显示为空白源' });
  if (!feed.link) issues.push({ level:'bad', msg:'缺少 channel/link，阅读器无法回跳站点主页' });
  if (!feed.description) issues.push({ level:'warn', msg:'缺少订阅源简介，目录站抓取时没有摘要可展示' });
  if (!feed.self) issues.push({ level:'warn', msg:'缺少 atom:link rel="self"，部分阅读器无法自动发现真实地址' });
  if (!items.length) issues.push({ level:'bad', msg:'没有任何条目，订阅源为空' });
  if (items.length > 50) issues.push({ level:'warn', msg:'共 ' + items.length + ' 条，建议只保留最近 20–50 条以控制体积' });

  var seen = {}, dupes = 0, noLink = 0, noDate = 0, shortDesc = 0, future = 0, unsorted = false;
  var now = feed.now ? parseDate(feed.now) : null;
  var prev = null;
  for (var i = 0; i < items.length; i++){
    var it = items[i];
    var g = it.guid || '';
    if (!g) dupes++;
    else if (seen[g]) dupes++;
    else seen[g] = 1;
    if (!it.url) noLink++;
    var d = parseDate(it.date);
    if (!d) noDate++;
    else {
      if (now && d.getTime() > now.getTime() + 86400000) future++;
      if (prev && d.getTime() > prev.getTime()) unsorted = true;
      prev = d;
    }
    if (it.description && it.description.length < 20) shortDesc++;
    if (!it.title) issues.push({ level:'bad', msg:'第 ' + (i + 1) + ' 条缺少标题' });
  }
  if (dupes) issues.push({ level:'bad', msg:dupes + ' 条 guid 缺失或重复，阅读器会反复推送或直接吞掉' });
  if (noLink) issues.push({ level:'warn', msg:noLink + ' 条没有 link，点击标题无处可去' });
  if (noDate) issues.push({ level:'warn', msg:noDate + ' 条没有日期，阅读器只能按抓取顺序排列' });
  if (future) issues.push({ level:'warn', msg:future + ' 条日期在未来，部分阅读器会直接隐藏' });
  if (unsorted) issues.push({ level:'warn', msg:'条目未按时间倒序排列，建议最新的放最前面' });
  if (shortDesc) issues.push({ level:'warn', msg:shortDesc + ' 条摘要短于 20 字，信息量偏低' });

  var score = 100;
  for (var j = 0; j < issues.length; j++) score -= (issues[j].level === 'bad' ? 20 : 8);
  score = Math.max(0, score);
  return { issues: issues, score: score, grade: gradeOf(score) };
}

function gradeOf(score){
  if (score >= 90) return 'A';
  if (score >= 75) return 'B';
  if (score >= 60) return 'C';
  if (score >= 40) return 'D';
  return 'F';
}

function feedStats(items){
  items = items || [];
  var dates = [], chars = 0, tagCount = {}, withLink = 0;
  for (var i = 0; i < items.length; i++){
    var d = parseDate(items[i].date);
    if (d) dates.push(d.getTime());
    chars += (items[i].description || '').length;
    if (items[i].url) withLink++;
    var tg = items[i].tags || [];
    for (var t = 0; t < tg.length; t++) tagCount[tg[t]] = (tagCount[tg[t]] || 0) + 1;
  }
  dates.sort(function(a, b){ return a - b; });
  var span = dates.length > 1 ? Math.round((dates[dates.length - 1] - dates[0]) / 86400000) : 0;
  var topTags = Object.keys(tagCount).sort(function(a, b){
    return tagCount[b] - tagCount[a] || (a < b ? -1 : 1);
  }).slice(0, 8).map(function(k){ return { tag: k, n: tagCount[k] }; });
  return {
    count: items.length,
    withLink: withLink,
    avgChars: items.length ? Math.round(chars / items.length) : 0,
    spanDays: span,
    perWeek: span > 0 ? Math.round(items.length / (span / 7) * 10) / 10 : 0,
    first: dates.length ? rfc3339(new Date(dates[0])) : '',
    last: dates.length ? rfc3339(new Date(dates[dates.length - 1])) : '',
    topTags: topTags
  };
}

var RssForgePure = {
  escapeXml: escapeXml, parseDate: parseDate, rfc822: rfc822, rfc3339: rfc3339,
  parseItems: parseItems, buildRss: buildRss, buildAtom: buildAtom, buildJsonFeed: buildJsonFeed,
  lintFeed: lintFeed, feedStats: feedStats, latestDate: latestDate, gradeOf: gradeOf
};
if (typeof module !== 'undefined' && module.exports) module.exports = RssForgePure;
if (typeof window !== 'undefined') window.RssForgePure = RssForgePure;
